    "originalFileName": "DEPUIS_Daphne_Atelier_8_Construire_des_grill_2026-10-19.docx",
    "formattedFileName": "DEPUIS_Daphne_Atelier_8_Construire_des_grill_2026-10-19.docx",
    "fileType": "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
    "fileSize": 27080,
    "fileUrl": "/travaux-etudiants/DEPUIS_Daphne_Atelier_8_Construire_des_grill_2026-10-19.docx",
