    "originalFileName": "TRAORE_Amadou_Bamba_Exercice_1_Diagnostic_de_compe_2026-10-01.docx",
    "formattedFileName": "TRAORE_Amadou_Bamba_Exercice_1_Diagnostic_de_compe_2026-10-01.docx",
    "fileType": "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
    "fileSize": 22138,
    "fileUrl": "/travaux-etudiants/TRAORE_Amadou_Bamba_Exercice_1_Diagnostic_de_compe_2026-10-01.docx",
    "dataUrl": "",
